import json, numpy as np, redis
r=redis.Redis(decode_responses=True)
recs=[json.loads(l) for l in open('/data/articles.jsonl')]
ids=[x['id'] for x in recs]
X=np.array([x['embedding'] for x in recs]); X/=np.linalg.norm(X,axis=1,keepdims=True)
idx={a:i for i,a in enumerate(ids)}
def parse(res):
    if isinstance(res, dict): return {k: float(v) for k,v in res.items()}
    if isinstance(res, list) and len(res)==1 and isinstance(res[0], dict): return {k: float(v) for k,v in res[0].items()}
    return {res[i]: float(res[i+1]) for i in range(0,len(res),2)}
for t in [0,5,42]:
    q=X[t].copy()
    for key in ['tv_noquant','tv_quant']:
        res=r.execute_command('VSIM',key,'VALUES','64',*[repr(float(x)) for x in q],'COUNT','5','WITHSCORES')
        d=parse(res)
        tops=list(d.items())[:2]
        print(key, 'self rank:', [k for k in d].index(ids[t]) if ids[t] in d else 'miss',
              ' scores:', [(k, round(v,4), round(float(X[idx[k]]@q),4)) for k,v in tops])
