cd /app && python3 - <<'EOF'
import json, numpy as np, redis, time
r=redis.Redis(decode_responses=True)
recs=[json.loads(l) for l in open('/data/articles.jsonl')]
ids=[x['id'] for x in recs]
X=np.array([x['embedding'] for x in recs], dtype=np.float64); X/=np.linalg.norm(X,axis=1,keepdims=True)
idx={a:i for i,a in enumerate(ids)}
def parse(res):
    if isinstance(res, dict): return list(res.keys())
    if isinstance(res, list) and res and isinstance(res[0], dict): return list(res[0].keys())
    return res[0::2]
rng=np.random.default_rng(11)
configs={'hnsw_default':[], 'hnsw_ef500':['EF','500'], 'truth':['TRUTH']}
bad={k:0 for k in configs}
t0=time.time()
for t in range(500):
    q=rng.normal(size=64); q/=np.linalg.norm(q)
    exact=[ids[i] for i in np.argsort(-(X@q))[:5]]
    for name,opt in configs.items():
        got=parse(r.execute_command('VSIM','tv_noquant','VALUES','64',*[repr(float(x)) for x in q],'COUNT','5',*opt))
        if list(got)[:5]!=exact: bad[name]+=1
print('mismatches /500:', bad, 'elapsed %.1fs'%(time.time()-t0))
EOF
